import org.junit.Test;
import static org.junit.Assert.*;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class OnlineStockSpanTest {

    @InjectMocks
    private OnlineStockSpan onlineStockSpan;

    @Mock
    private int[] pricesMock;

    @Mock
    private int priceMock1;

    @Mock
    private int priceMock2;

    @Test
    public void next_[Low]Test() {
        when(pricesMock[0]).thenReturn(priceMock1);
        assertEquals(1, onlineStockSpan.next(priceMock1));
    }

    @Test
    public void next_[High]Test() {
        when(pricesMock[0]).thenReturn(priceMock2);
        assertEquals(1, onlineStockSpan.next(priceMock2));
    }

    @Test
    public void next_[Equal]Test() {
        when(pricesMock[0]).thenReturn(priceMock1);
        when(pricesMock[1]).thenReturn(priceMock1);
        assertEquals(1, onlineStockSpan.next(priceMock1));
    }

    @Test
    public void calculateSpans_[Empty]Test() {
        int[] result = onlineStockSpan.calculateSpans(new int[]{});
        assertNotNull(result);
        assertEquals(0, result.length);
    }

    @Test
    public void calculateSpans_[SingleElement]Test() {
        int[] result = onlineStockSpan.calculateSpans(new int[]{priceMock1});
        assertNotNull(result);
        assertEquals(1, result.length);
    }

    @Test
    public void calculateSpans_[MultipleElements]Test() {
        when(pricesMock[0]).thenReturn(priceMock1);
        when(pricesMock[1]).thenReturn(priceMock2);
        when(pricesMock[2]).thenReturn(priceMock3);

        int[] result = onlineStockSpan.calculateSpans(new int[]{priceMock1, priceMock2, priceMock3});
        assertNotNull(result);
        assertEquals(3, result.length);
    }

    @Test
    public void calculateSpans_[MultipleElementsSpan]Test() {
        when(pricesMock[0]).thenReturn(priceMock1);
        when(pricesMock[1]).thenReturn(priceMock1);
        when(pricesMock[2]).thenReturn(priceMock2);

        int[] result = onlineStockSpan.calculateSpans(new int[]{priceMock1, priceMock1, priceMock2});
        assertNotNull(result);
        assertEquals(3, result.length);
    }
}
